package main

import (
    "context"
    "testing"
)

func TestHistoryDecodeAdmissionDoesNotLeakCanceledLease(t *testing.T) {
    release, err := acquireHistoryHeavyBudget(context.Background(), "decode-user", 1)
    if err != nil { t.Fatal(err) }
    release()
    if _, err := acquireHistoryHeavyBudget(context.Background(), "decode-user", 1); err != nil { t.Fatal(err) }
}
